const formatPrice = (waarde) => {
  const getal = Number(waarde);
  if (isNaN(getal)) return waarde;
  return getal.toLocaleString('nl-NL', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

const formatKm = (waarde) => {
