  foutmelding.value = ''
  zoekDuur.value = null
}

async function zoekProduct() {
  foutmelding.value = ''
  statistieken.value = null
  zoekDuur.value = null

  if (!zoekterm.value) {
    return
  }

  laden.value = true
  const start = performance.now()   // <-- NEW
  try {
    let url = `/api/stats?term=${encodeURIComponent(zoekterm.value)}`
